 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Infer the frame color from full-width/full-height separator lines.
    freq = {}
    for r in grid:
        if r[0] and all(x == r[0] for x in r):
            freq[r[0]] = freq.get(r[0], 0) + 1
    for c in range(w):
        v = grid[0][c]
        if v and all(grid[r][c] == v for r in range(h)):
            freq[v] = freq.get(v, 0) + 1
    frame = max(freq, key=freq.get)
    sr = [r for r in range(h) if all(x == frame for x in grid[r])]
    sc = [c for c in range(w) if all(grid[r][c] == frame for r in range(h))]
    rb, cb = [-1] + sr + [h], [-1] + sc + [w]
    cells = []
    for ri in range(len(rb)-1):
        row = []
        for ci in range(len(cb)-1):
            row.append((rb[ri]+1, rb[ri+1], cb[ci]+1, cb[ci+1]))
        cells.append(row)
    out = [r[:] for r in grid]
    nr, nc = len(cells), len(cells[0])
    # In each adjacent 2x2 block, a three-present motif marks the omitted tile.
    # Reflect the nearest motif through the divider into the omitted tile.
    for r in range(nr-1):
        for c in range(nc-1):
            qs = [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            colors = {grid[i][j] for rr,cc in qs
                      for a,b,x,y in [cells[rr][cc]]
                      for i in range(a,b) for j in range(x,y)
                      if grid[i][j] not in (0, frame)}
            for color in colors:
                present = []
                for rr,cc in qs:
                    a,b,x,y = cells[rr][cc]
                    present.append(any(grid[i][j] == color for i in range(a,b) for j in range(x,y)))
                if sum(present) != 3:
                    continue
                miss = present.index(False)
                mr,mc = qs[miss]
                # Find a present tile sharing a divider with the empty tile.
                sources = [k for k,p in enumerate(present) if p and
                           ((qs[k][0] == mr and abs(qs[k][1]-mc) == 1) or
                            (qs[k][1] == mc and abs(qs[k][0]-mr) == 1))]
                if not sources:
                    continue
                # A horizontal-row neighbor takes precedence, as demonstrated.
                sources.sort(key=lambda k: (qs[k][0] != mr, k))
                sr0,sc0 = qs[sources[0]]
                a,b,x,y = cells[sr0][sc0]
                da,db,dx,dy = cells[mr][mc]
                if (b-a, y-x) != (db-da, dy-dx):
                    continue
                fu, fl = sr0 != mr, sc0 != mc
                for i in range(b-a):
                    for j in range(y-x):
                        si = b-1-i if fu else a+i
                        sj = y-1-j if fl else x+j
                        if grid[si][sj] == color:
                            out[da+i][dx+j] = color
    return out
